"CARCU":{"num":"11.05.01","level":3,"parent":"CO2CU","title":"Carbonation Curing","desc":"Focuses on carbonation curing in 3DCP, with emphasis on exposure mechanisms, transport-driven deterioration, cracking, retained properties, and long-term resistance.","terms":["Carbonation Curing","curing","postprocessing","finishing","surface treatment","machining"],"color":"#FAEAF0"},
